insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('f45ae704-ba00-477b-8888-2cac2583b169', '0c4d69fa-cd73-4459-ad0b-e20b0ff5ac5f', $$bron 1: Fynes Moryson over het huis van Tycho Brahe (1593)$$,
   $$geschiedenis-havo-2023-ii-ontdekkers-en-hervormers-bron1.png$$,
   $$bron 1 In 1593 beschrijft de Engelsman Fynes Moryson het huis van de Deense sterrenkundige Tycho Brahe:
Op de wanden van dit kleine huis waren portretten van alle beroemde astronomen geschilderd, voorzien van bijpassende teksten: "God groet de helden. Gegroet oude Timocharis¹), die het vóór anderen heeft gedurfd om de uithoeken van de hemel te bestuderen. Ook jij Hipparchus1), die gemeten heeft wat de banen van de zon en de maan zijn en alle sterren aan de hemel." (…) Op de beste plaats had deze heer Tycho Brahe zijn eigen portret laten aanbrengen, met de volgende tekst: "Met het oude en met mijn eigen onderzoek heb ik de plek van de sterren bepaald. Laat het nageslacht mijn werk maar beoordelen."
noot 1 Timocharis en Hipparchus zijn Griekse astronomen die leefden in de derde en tweede eeuw voor Christus.$$, 'inline'),
  ('142df9bf-4630-4931-b1cf-c6612de6a6c9', 'c37448e2-7737-490b-9089-9576581f18c7', $$bron 2: Mayflower Compact (1620)$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-bron2.png$$,
   $$bron 2 Bij aankomst in Amerika in 1620 stellen kolonisten een overeenkomst op. In dit Mayflower Compact staat:
In de naam van God, Amen. Wij, die dit document hebben ondertekend, zijn de trouwe onderdanen van onze ontzagwekkende soevereine heer, koning Jacobus1) (…). Na een reis te hebben ondernomen om de eerste kolonie te stichten in de noordelijke delen van Virginia, voor de glorie van God, de bevordering van het christelijk geloof en de eer van onze koning en ons land, verbinden en verenigen we onszelf tot een burgerlijk politiek lichaam met deze overeenkomst. (…) voor onze betere organisatie en behoud (…). Op grond hiervan stellen wij van tijd tot tijd rechtvaardige wetten, verordeningen, aktes, grondregels en ambten op, die wij het meest geschikt achten voor het algemene welzijn van de kolonie, waaraan wij alle gepaste onderwerping en gehoorzaamheid beloven.
noot 1 Dit is Jacobus I, de Engelse koning.$$, 'inline'),
  ('b2454418-2a58-4423-b492-6af160e2bf29', 'c37448e2-7737-490b-9089-9576581f18c7', $$bron 5: Brits overheidsrapport over arbeiderswoningen (1839)$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-bron5.png$$,
   $$bron 5 In 1839 liet de Britse regering officieel onderzoek doen naar de huisvesting van arbeiders. De onderzoekers schreven in hun rapport over arbeiderswoningen:
In sommige van deze huizen staan wel zes tot acht bedden in een kamer; in kleinere kamers staan noodzakelijkerwijs minder bedden. Het schijnt het gebruik te zijn (…) om zoveel mogelijk bedden in elke kamer te proppen en ze staan vaak zo dicht op elkaar dat er nauwelijks plek is om er tussen door te lopen. ''s Nachts ziet het er helemaal dieptriest uit: de bedden volgepakt met mannen, vrouwen en kinderen (…). De verstikkende stank en warmte zijn bijna onverdraaglijk als je binnenkomt en maken direct duidelijk hoe ongezond het is.$$, 'inline'),
  ('e5de9c15-6b1b-4e62-ac76-362028ae68eb', 'c37448e2-7737-490b-9089-9576581f18c7', $$bron 6: Eliza Cook over de Wereldtentoonstelling in Londen (1851)$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-bron6.png$$,
   $$bron 6 In 1851 schrijft Eliza Cook in een door haar gepubliceerd tijdschrift over de vele mensen van het platteland die per trein naar de wereldtentoonstelling in Londen reizen:
Voor het eerst heeft de dagtoerist dit jaar de metropool bezocht. Hij had nooit gedacht dat hij Londen zou zien in zijn leven, maar de Tentoonstelling trekt hem ernaar toe en de goedkope treinkaartjes maken het mogelijk de reis te maken. (…) En dan, bij de Grote Tentoonstelling, daar zien we de dagtoerist in al zijn glorie! (…) Daar maakt hij zijn mand open en toont zijn ham en kaas van het platteland. Die smaken goed na zijn lange tocht langs Oostenrijkse, Russische, Franse en Amerikaanse afdelingen. Om nog maar te zwijgen over de trots die hem ertoe bracht ook de producten uit de eigen streken te bekijken. Uiteindelijk gelooft hij dat het ''Groot-Brittannië is dat de klok slaat'' en hoewel de Amerikanen ervan uitgaan dat zij het beste zijn, gelooft de dagtoerist dat ''Groot-Brittannië de Amerikanen verslaat''.$$, 'inline'),
  ('219da00c-9cc6-4cdc-98a4-ca896e88d5b3', 'c37448e2-7737-490b-9089-9576581f18c7', $$bron 7: David Livingstone over zijn reis door Afrika (1857)$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-bron7.png$$,
   $$bron 7 De ontdekkingsreiziger David Livingstone zegt in 1857 over zijn reis door Afrika:
Angola is wonderbaarlijk vruchtbaar en produceert alle soorten luxe tropische planten. Toen ik doorging naar de vallei van (de rivier) de Kwango, was de stengel van het gras zo dik als een ganzenveer en het torende boven mijn hoofd uit, hoewel ik op mijn os zat. Katoen wordt geproduceerd in grote overvloed, hoewel slechts geweven tot gewone stof. (...) Als ik terugga naar dat land is mijn doel om het verkeer langs de oevers van de Zambezi te openen en ook om het evangelie te prediken. De inwoners van Centraal-Afrika willen heel graag handel drijven, maar hun enige handel is momenteel in slaven, waarvan de armere mensen een regelrechte afschuw hebben.$$, 'inline'),
  ('0bdc2aa6-6946-41c4-82a6-1afa81fdc580', 'ac61c6ec-0e98-4eec-bd90-6b3c70319866', $$bron 3: instructie van de VOC voor een reis naar Australië (1622)$$,
   $$geschiedenis-havo-2023-ii-regenten-en-vorsten-bron3.png$$,
   $$bron 3 In september 1622 stuurt de Verenigde Oost-Indische Compagnie (VOC) twee schepen naar de pas ontdekte kust van Australië met de instructie:
Ga op verschillende plekken aan land en onderzoek de kust grondig om vast te stellen of het wel of niet bewoond is, hoe het land eruit ziet en onderzoek de bevolking, hun steden en dorpen. Hoe hun rijken zijn verdeeld, hun godsdienst en hun politiek, hun oorlogen, hun rivieren, de vorm van hun schepen, hun visgronden, hun werkplaatsen en ambachten. (…) Aan al deze wetenswaardigheden en verder alles wat de moeite waard is, moet je aandacht schenken, en die zorgvuldig opnemen in het logboek van de reis.$$, 'inline'),
  ('2b86f8a5-02e6-4121-a9a4-640e746d408f', 'e757b23c-a9f1-4abe-9e34-a39827a119d2', $$bron 4: prent uit Nieuwe proeve van kleine gedichten voor kinderen van Pieter 't Hoen (1778)$$,
   $$geschiedenis-havo-2023-ii-pruiken-en-revoluties-bron4.png$$,
   $$bron 4 In 1778 publiceert Pieter ''t Hoen het boek Nieuwe proeve van kleine gedichten voor kinderen met daarin deze afbeelding:
[Afbeelding] Prent: in een kamer wijst een vader streng naar zijn zoontje, dat huilend voor hem staat; de vader houdt gescheurde, armoedige kleren omhoog.
Toelichting: De prent hoort bij een gedicht waarin Piet tegen zijn vader zegt dat hij niet langer naar school wil. De prent toont het moment dat Piets vader hem armoedige kleren geeft en zegt dat als Piet lui wil zijn, hij dan maar een bedelaar moet worden. Piet krijgt daarna spijt en wil toch weer naar
⚠️ CONTROLEREN: de toelichting is in de PDF van ExamenCentraal onderaan afgekapt (eindigt met ''wil toch weer naar'').$$, 'inline'),
  ('1c2b7dee-3883-4ed3-8073-a1eb68441674', '3124c956-723a-4bf0-80f3-bd43a589a6f4', $$bron 8: toespraak van Ottilie Baader (1902)$$,
   $$geschiedenis-havo-2023-ii-burgers-en-stoommachines-bron8.png$$,
   $$bron 8 Ottilie Baader, een van de oprichtsters van de eerste vrouwenvakbond in Duitsland, zegt in 1902 tijdens een bijeenkomst voor vrouwenkiesrecht:
Onder de vrouwelijke activisten bevinden zich zowel academisch geschoolde vrouwen1) als arbeidsters, waarvan we weten dat ze de arbeiderspartij
volmondig steunen. Ik hoef hierbij alleen maar te wijzen naar kameraad Zetkin2), die zelf een academisch geschoolde dame is. Ze staat dicht bij ons, ze is als familie. Maar er zijn ook academisch geschoolde dames die het
alleen maar belangrijk vinden om zich zo nu en dan publiekelijk te laten zien door een toespraak te houden voor een groot gezelschap. De meeste
arbeidsters begrijpen deze dames helemaal niet, deze zogenaamde paradepaarden,
noot 1 vrouwen die een studie hebben gevolgd aan een universiteit noot 2 Clara Zetkin was een Duitse activiste voor vrouwenrechten.
⚠️ CONTROLEREN: het citaat is in de PDF van ExamenCentraal onderaan het kader afgekapt (eindigt met ''deze zogenaamde paradepaarden,'').$$, 'inline'),
  ('5c7dc208-99cf-42c2-b1c2-62e6cd086bcf', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', $$bron 9: ingezonden brief van een zakenman over Duitsland (1922)$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-bron9.png$$,
   $$bron 9 In 1922 verschijnt in meerdere Britse kranten dezelfde ingezonden brief van een zakenman die Duitsland heeft bezocht:
De grootste fraude uit de geschiedenis vindt nu plaats in Duitsland, met de volledige steun van de bevolking. Deze fraude vindt plaats onder de neus van de geallieerden. Duitsland is welvarend. Het bruist van de activiteiten. Ik heb me tijdens mijn bezoek verbaasd over de luxe en welvaart van de bevolking. Er is bijna geen armoede. En toch is dit een land dat vastberaden is haar schulden niet te betalen. (…) En als ze onder haar schulden uit is gekomen (terwijl haar schuldeisers wankelen onder steeds zwaardere lasten) zal haar volgende ''samenzwering'' zijn om haar koloniën terug te krijgen. Het is een natie van acteurs.$$, 'inline'),
  ('9e363ac7-16d4-4efd-8339-d1677a9f71c6', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', $$bron 10: Gareth Jones over werkverschaffingskampen in Duitsland (1933)$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-bron10.png$$,
   $$bron 10 In 1933 reist de journalist Gareth Jones door Duitsland. Hij schrijft in een artikel in de Britse krant Western Mail & South Wales News over de aanpak van de werkloosheid in Duitsland door middel van kampen waarin werklozen een tijd wonen en werken:
In welke mate lossen deze kampen het probleem van de werkloosheid op? Ze streven er vooral naar om jonge werklozen te helpen, afgelopen zomer werkten 290.000 mannen in deze kampen. Ze hopen dat deze zomer er tussen de 300.000 en 400.000 zullen worden ingeschreven. Maar nu staat het hele systeem op losse schroeven, want Hitler is aan de macht gekomen en er wordt gevreesd dat hij de basis van vrijwilligheid zal vernietigen en dat hij het verplicht gaat stellen (…). Als Wales net zoveel had gedaan voor de werklozen als Duitsland, dan waren er hier nu 300 kampen met 10.000 jongemannen tussen de 18 en 25 jaar, die bezig waren met nuttig werk, die laarzen repareerden, die samen zongen, die zich lichamelijk inspanden, voetbal of cricket speelden en met elkaar over van alles discussieerden.$$, 'inline'),
  ('ca76e90d-c813-4566-b196-393ebf6d201d', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', $$bron 12: foto uit het DDR-partijblad bij 'De eerste Duitser in de ruimte' (1978)$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-bron12.png$$,
   $$bron 12 Foto uit 1978 bij het artikel met de titel De eerste Duitser in de ruimte: een Oost-Duitse burger, in het partijblad van de Communistische Partij in de DDR:
[Afbeelding] Foto van twee kosmonauten in ruimtepak die bij een trap van een raket staan en zwaaien.
Toelichting: De kosmonaut Sigmund Jähn (voor) verbleef acht dagen in de ruimte, waar hij samen met de Russische kosmonaut Valeri Bykovski (achter) onderzoek deed aan boord van het Russische ruimtestation Saljoet 6.$$, 'inline'),
  ('81e23791-3784-4c6c-be29-1d03ce7d9024', 'cb2f2ae6-28b2-45c8-9138-c389fee0fc1e', $$bron 11: Tevfik Tokac over zijn werk bij radiatorenfabriek Duintjer (jaren 1960)$$,
   $$geschiedenis-havo-2023-ii-nederland-1948-2008-bron11.png$$,
   $$bron 11 Tevfik Tokac, die uit Turkije komt, vertelt over zijn werk bij de Veendamse radiatorenfabriek Duintjer begin jaren 1960:
Wij waren echt vakmensen en vroegen ons af hoe het mogelijk was. Bij Duintjer werd nog gelast met de hand en werden de radiatoren verplaatst door mensen. Mankracht was erg belangrijk. We begrepen hier helemaal niets van. In Zonguldak [in Turkije] zouden we een dergelijke werkplaats niet eens fabriek noemen, maar atelier.$$, 'inline'),
  ('c694df42-6260-45f9-808f-2a1fe1ad81e2', 'cb2f2ae6-28b2-45c8-9138-c389fee0fc1e', $$bron 13: prent van Opland over het kabinet-Lubbers (1983)$$,
   $$geschiedenis-havo-2023-ii-nederland-1948-2008-bron13.png$$,
   $$bron 13 Prent van de tekenaar Opland uit 1983:
[Afbeelding] Prent: een gebogen man met een bijl met het opschrift LUBBERS in zijn hoofd; erboven staat ''Pakken van de zwakken?'' en eronder ''NEEN''.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('dea0dd2a-4662-4e19-830f-36b9caa95bd7', '74998a97-dbb9-47d8-83d9-ae35d8b828ec', 1,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Pruiken en revoluties — overig (1700-1800)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["chronologie", "ontdekkingsreizen", "East India Company", "Franse Revolutie", "industriële revolutie", "Koude Oorlog"]'::jsonb,
   $$Chronologisch ordenen van zes gegevens over verdwenen ontdekkingsreizigers uit verschillende tijdvakken.$$,
   $$geschiedenis-havo-2023-ii-door-de-tijd-heen-vraag1.png$$, $$De volgende gegevens over de verdwijning van ontdekkingsreizigers staan in willekeurige volgorde:
1 Enkele jaren na de Eerste Wereldoorlog verdween Percy Fawcett tijdens zijn zoektocht naar een verdwenen stad in de Braziliaanse jungle.
2 Er ontstonden complottheorieën over de verdwijning van Peng Jiamu in de Lop-woestijn omdat de Chinese regering daar atoomproeven hield.
3 John Knight verdween toen hij voor de pas opgerichte East India Company een doorgang zocht tussen de Atlantische Oceaan en de Stille Oceaan.
4 Koning Lodewijk XVI zou vlak voor zijn executie tijdens de Franse democratische revolutie gevraagd hebben naar nieuws over Jean-François de La Pérouse, die in Polynesië was verdwenen.
5 Sir John Franklin wilde met twee van de eerste Britse stoomschepen de Canadese poolcirkel onderzoeken. Hij en zijn hele bemanning verdwenen op de ijsvlakte.
6 Vasco de Ataíde verdween op een windstille nacht, vlak voordat zijn expeditiegenoten als een van de eerste Europeanen aan land gingen in Zuid-Amerika. 2p 1 Zet deze gegevens in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('9624a9d3-1be8-421a-929c-807b287ff98b', '74998a97-dbb9-47d8-83d9-ae35d8b828ec', 14,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["chronologie", "Verdrag van Versailles", "Anschluss", "bezettingszones", "Ostpolitik", "val van het IJzeren Gordijn"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen uit het leven van Otto von Habsburg.$$,
   $$geschiedenis-havo-2023-ii-door-de-tijd-heen-vraag14.png$$, $$De volgende gebeurtenissen uit het leven van Otto von Habsburg (1912-2011), de laatste kroonprins van Oostenrijk-Hongarije, staan in willekeurige volgorde:
1 De Oostenrijkse nationaalsocialistische regering wilde Otto von Habsburg laten arresteren.
2 In interviews bekritiseerde Otto von Habsburg de Ostpolitik van Willly Brandt.
3 Kort nadat de Vrede van Versailles werd getekend ging de familie van Otto von Habsburg in ballingschap in Zwitserland.
4 Op de dag dat Hongarije als eerste lid van het Warschaupact de grensovergang met het westen opende, organiseerde Otto von Habsburg de Pan-Europese picknick.
5 Otto von Habsburg pleitte voor de uitbreiding van de Europese Unie met Oost-Europese landen.
6 Tijdens de Tweede Conferentie van Quebec stelde Otto von Habsburg voor om de Oostenrijkse bezettingszone van de westerse geallieerden te vergroten ten koste van de Sovjetzone. 2p 14 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('2b2a1096-61db-40c4-8aa2-e31a4ec08ef2', '0c4d69fa-cd73-4459-ad0b-e20b0ff5ac5f', 2,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["renaissance", "klassieke Oudheid", "humanisme", "wetenschappelijke belangstelling", "individualisme", "bronverwijzing"]'::jsonb,
   $$Met bron 1 aantonen dat Tycho Brahe past bij twee kenmerkende aspecten van de zestiende eeuw.$$,
   $$geschiedenis-havo-2023-ii-ontdekkers-en-hervormers-vraag2.png$$, $$Gebruik bron 1. Uit deze bron blijkt dat Tycho Brahe past bij verschillende kenmerkende aspecten van de zestiende eeuw. 4p 2 Toon dit aan voor twee verschillende kenmerkende aspecten van de zestiende eeuw en ondersteun je antwoord telkens met een andere verwijzing naar de bron.$$, array['f45ae704-ba00-477b-8888-2cac2583b169']::uuid[]),
  ('9185d750-cc1a-472c-b3ce-f63477c62061', '0c4d69fa-cd73-4459-ad0b-e20b0ff5ac5f', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["kenmerkend aspect", "Europese expansie", "plantagekoloniën", "slavernij", "Amerikaanse Onafhankelijkheidsoorlog", "democratische revoluties"]'::jsonb,
   $$Bij drie liedjes uit de vroegmoderne tijd telkens het passende kenmerkende aspect noemen.$$,
   $$geschiedenis-havo-2023-ii-ontdekkers-en-hervormers-vraag4.png$$, $$Drie gegevens over liedjes in de vroegmoderne tijd:
1 In de zestiende eeuw zongen inheemse volken in Amerika liedjes over roofzuchtige Spanjaarden met woeste paarden.
2 In de achttiende eeuw werd op de suikerrietvelden van Barbados een Afrikaans liedje gezongen met de tekst "meester kocht mij, hij zal me niet doden".
3 In de achttiende eeuw zongen Amerikaanse kolonisten het liedje Yankee Doodle, waarmee ze de Britse troepen bespotten. 3p 4 Noem voor elk liedje apart het kenmerkend aspect uit die tijd dat bij het liedje past. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('bce43761-b598-4855-9448-c06cada05118', 'c37448e2-7737-490b-9089-9576581f18c7', 5,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Pilgrim Fathers", "Mayflower Compact", "zelfbestuur", "vestigingskolonie", "Jacobus I", "bronverwijzing"]'::jsonb,
   $$Een politiek motief en een machtsbeperking van Jacobus I aanwijzen die het Mayflower Compact belangrijk maken.$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-vraag5.png$$, $$Gebruik bron 2. Historici beschouwen het Mayflower Compact als een belangrijk document voor de politieke verhouding tussen Engeland en de kolonisten in Noord-Amerika. 3p 5 Geef hiervoor een argument door:
− zonder bron aan te geven welk politiek motief de opstellers van het document hebben om hun trouw aan Jacobus I te benadrukken, en
− met bron uit te leggen dat de kolonisten met het Mayflower Compact de macht van Jacobus I willen beperken.$$, array['142df9bf-4630-4931-b1cf-c6612de6a6c9']::uuid[]),
  ('cf4f4ce0-9ef5-4bfa-83c7-1577eeeb4ecd', 'c37448e2-7737-490b-9089-9576581f18c7', 9,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["abolitionisme", "verbod op slavenhandel", "slavernij", "Suriname", "Royal Navy", "Brits beleid"]'::jsonb,
   $$Uitleggen waarom de Britse regering in 1840 protesteerde tegen de aankoop van Afrikaanse mannen voor het Surinaamse soldatenkorps.$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-vraag9.png$$, $$In 1840 werden voor het Surinaamse soldatenkorps (zie vraag 8) vijftig mannen rechtstreeks in Afrika gekocht. De Britse regering protesteerde hiertegen. 2p 9 Leg uit waarom de Britse regering protesteerde tegen deze aankoop van de Afrikaanse mannen.
(De vraag verwijst naar vraag 8; die staat in het themablok ''Pruiken en Revoluties''.)$$, array[]::uuid[]),
  ('f08317b7-7789-411c-96d4-56d27affce0e', 'c37448e2-7737-490b-9089-9576581f18c7', 10,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["industriële revolutie", "sociale kwestie", "arbeiderswoningen", "urbanisatie", "betrouwbaarheid", "representativiteit"]'::jsonb,
   $$Uitleggen dat de arbeidershuisvesting een gevolg was van de industrialisatie en waarom het overheidsrapport betrouwbaar en representatief is.$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-vraag10.png$$, $$Gebruik bron 5. Historici beschouwen de informatie uit dit overheidsrapport als betrouwbaar en als representatief voor een onderzoek naar de arbeidershuisvesting in de negentiende eeuw. 4p 10 Licht dit toe door:
− uit te leggen dat de beschreven arbeidershuisvesting een gevolg is van de industrialisatie van Groot-Brittannië, en
− zonder bron apart te verklaren dat historici de informatie in dit rapport als betrouwbaar en als representatief beschouwen juist omdat het een overheidsonderzoek betreft.$$, array['b2454418-2a58-4423-b492-6af160e2bf29']::uuid[]),
  ('273c8d36-d46a-491f-bba4-4de252732972', 'c37448e2-7737-490b-9089-9576581f18c7', 11,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Wereldtentoonstelling 1851", "industriële revolutie", "spoorwegen", "nationalisme", "massaconsumptie", "bronverwijzing"]'::jsonb,
   $$Met bron 6 uitleggen op welke twee manieren de industriële revolutie het gevoel van eenheid onder de Britten versterkte.$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-vraag11.png$$, $$Gebruik bron 6. Een bewering: De industriële revolutie versterkt het gevoel van eenheid onder de Britten. 4p 11 Leg met behulp van de bron uit dat de industriële revolutie op twee verschillende manieren bijdraagt aan het gevoel van eenheid.$$, array['e5de9c15-6b1b-4e62-ac76-362028ae68eb']::uuid[]),
  ('edb68dbe-e6c0-4b1a-b720-8972ad87283a', 'c37448e2-7737-490b-9089-9576581f18c7', 12,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["modern imperialisme", "motieven", "Livingstone", "zendingsdrang", "Afrika", "bronverwijzing"]'::jsonb,
   $$Met bron 7 twee verschillende motieven voor het modern imperialisme aantonen in de beschrijving van Livingstone.$$,
   $$geschiedenis-havo-2023-ii-het-britse-rijk-vraag12.png$$, $$Gebruik bron 7. In de beschrijving van Livingstone zijn motieven voor het modern imperialisme te herkennen. 4p 12 Toon dit aan voor twee verschillende motieven voor het modern imperialisme, waarbij je je antwoord telkens ondersteunt met een verwijzing naar de bron.$$, array['219da00c-9cc6-4cdc-98a4-ca896e88d5b3']::uuid[]),
  ('cb3cd304-8820-49e9-baa1-91f97b43c05d', 'ac61c6ec-0e98-4eec-bd90-6b3c70319866', 3,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["wetenschappelijke revolutie", "wetenschappelijke methode", "Galilei", "waarnemen", "kerk en wetenschap", "kenmerkend aspect"]'::jsonb,
   $$Uitleggen welke wetenschappelijke methode van de zeventiende eeuw Galilei met zijn uitspraak ondersteunde.$$,
   $$geschiedenis-havo-2023-ii-regenten-en-vorsten-vraag3.png$$, $$In 1615 schreef de sterrenkundige Galilei nadat hij kritiek had gekregen op zijn theorie over het heelal: "Ik geloof niet dat dezelfde God die ons zintuigen, verstand en intellect heeft gegeven, bedoelde dat we daar geen gebruik van zouden maken." 2p 3 Leg uit welke wetenschappelijke methode, die past bij de zeventiende eeuw, Galilei ondersteunde met deze uitspraak.$$, array[]::uuid[]),
  ('e061f39b-cba1-4b36-a266-c4af3fe3118b', 'ac61c6ec-0e98-4eec-bd90-6b3c70319866', 6,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["VOC", "Republiek", "Gouden Eeuw", "handelskapitalisme", "Europese expansie", "bronverwijzing"]'::jsonb,
   $$Een kenmerkend aspect bij de oprichting van de VOC noemen en uitleggen hoe de instructie het doel van de VOC ondersteunt.$$,
   $$geschiedenis-havo-2023-ii-regenten-en-vorsten-vraag6.png$$, $$Gebruik bron 3. In 1602 wordt in de Republiek de handelsonderneming VOC opgericht. 3p 6 Geef aan:
− welk kenmerkend aspect van de zeventiende eeuw past bij de oprichting van de VOC, en
− waardoor deze instructie het doel van de VOC ondersteunt, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['0bdc2aa6-6946-41c4-82a6-1afa81fdc580']::uuid[]),
  ('4e3df2ce-5c44-4af3-80fb-259027b1e34d', 'e757b23c-a9f1-4abe-9e34-a39827a119d2', 7,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Pruiken en revoluties — overig (1700-1800)"}]'::jsonb,
   '["Verlichting", "opvoeding", "verlicht denkbeeld", "kinderboeken", "verspreiding van ideeën", "bronverwijzing"]'::jsonb,
   $$Aangeven welk verlicht denkbeeld de prent verspreidt en verklaren waarom 't Hoen zijn boodschap met een prentenboek overbracht.$$,
   $$geschiedenis-havo-2023-ii-pruiken-en-revoluties-vraag7.png$$, $$Gebruik bron 4. Tijdens de Verlichting worden boeken met prenten voor kinderen gepubliceerd. 3p 7 Licht dit toe door:
− met een verwijzing naar de prent aan te geven welk verlicht denkbeeld wordt verspreid, en
− te verklaren dat Pieter ’t Hoen zijn boodschap met een boek met prenten overbrengt.$$, array['2b86f8a5-02e6-4121-a9a4-640e746d408f']::uuid[]),
  ('9f92c575-6398-410c-9c46-f6144272eaaf', 'e757b23c-a9f1-4abe-9e34-a39827a119d2', 8,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Pruiken en revoluties — overig (1700-1800)"}]'::jsonb,
   '["plantagekoloniën", "slavernij", "Suriname", "marronage", "plantage-economie", "kenmerkend aspect"]'::jsonb,
   $$Met de gegevens verklaren waarom plantage-eigenaren eerst tegen het soldatenkorps waren en waarom de soldaten onder druk stonden.$$,
   $$geschiedenis-havo-2023-ii-pruiken-en-revoluties-vraag8.png$$, $$In de achttiende eeuw richtte de gouverneur van de Nederlandse kolonie Suriname een soldatenkorps op, om een einde te maken aan opstanden en vernielingen door weggelopen slaafgemaakten. Voor het korps werden Surinaamse slaafgemaakte mannen geselecteerd. Enkele gegevens:
1 De vergoeding die plantage-eigenaren kregen voor een geselecteerde man was een stuk hoger dan de economische waarde van de slaafgemaakte.
2 Leden van het korps kregen een militaire training en wapens om te vechten.
3 Leden van het korps konden hun vrouwen en kinderen, die ze moesten achterlaten op de plantages, bezoeken. De plantage-eigenaren waren eerst tegen de oprichting van het korps, maar het korps bleek wel effectief. 2p 8 Verklaar, waarbij je je antwoord telkens ondersteunt met een ander gegeven:
− waardoor de plantage-eigenaren eerst tegen de oprichting van het korps waren, en
− waardoor de geselecteerde slaafgemaakten onder druk stonden om zich in te spannen voor het korps. Let op: je mag een gegeven maar één keer gebruiken$$, array[]::uuid[]),
  ('e61bce30-6f1f-44af-881f-8f4baa2b5369', 'f717c287-ecf5-47ce-96e8-81686f8f5efe', 18,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["dekolonisatie", "Koude Oorlog", "blokvorming", "nationalisme in koloniën", "verzet tegen imperialisme", "redeneren"]'::jsonb,
   $$Uitleggen hoe het dekolonisatieproces na de Tweede Wereldoorlog bijdroeg aan de Koude Oorlog.$$,
   $$geschiedenis-havo-2023-ii-tijd-van-wereldoorlogen-vraag18.png$$, $$Volgens sommige historici heeft het dekolonisatieproces na de Tweede Wereldoorlog bijgedragen aan de Koude Oorlog. 2p 18 Leg deze redenering uit.$$, array[]::uuid[]),
  ('10474469-5897-4f2b-8609-1eb07cb7c79d', '3124c956-723a-4bf0-80f3-bd43a589a6f4', 13,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["feminisme", "socialisme", "vrouwenkiesrecht", "emancipatiebewegingen", "arbeidersbeweging", "Clara Zetkin"]'::jsonb,
   $$Aangeven welk probleem binnen de feministische beweging Ottilie Baader noemt en bij welke politieke stroming haar kritiek past.$$,
   $$geschiedenis-havo-2023-ii-burgers-en-stoommachines-vraag13.png$$, $$Gebruik bron 8. Uit de bron blijkt een tegenstelling binnen de feministische beweging in Duitsland. 2p 13 Geef aan:
− welk probleem Ottilie Baader benoemt en
− bij welke politieke stroming haar kritiek past.$$, array['1c2b7dee-3883-4ed3-8073-a1eb68441674']::uuid[]),
  ('a10b105e-ed72-49f3-8d2f-e588dc790a1d', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', 15,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["herstelbetalingen", "Verdrag van Versailles", "Republiek van Weimar", "publieke opinie", "bruikbaarheid van een bron", "onderzoeksvraag"]'::jsonb,
   $$Uitleggen dat bron 9 minder bruikbaar is voor de Duitse economie in 1922 en meer voor de Britse publieke opinie over de herstelbetalingen.$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-vraag15.png$$, $$Gebruik bron 9. Stel: een onderzoek naar het stopzetten van de herstelbetalingen door de Duitse regering in 1922 heeft twee onderzoeksgebieden:
1 De economische situatie in Duitsland in 1922.
2 De publieke opinie in Groot-Brittannië over het stopzetten van de herstelbetalingen door de Duitse regering. 4p 15 Leg uit dat de bron:
− voor het eerste onderzoeksgebied minder bruikbaar is, en
− meer bruikbaar voor het tweede onderzoeksgebied.$$, array['5c7dc208-99cf-42c2-b1c2-62e6cd086bcf']::uuid[]),
  ('5b71dd47-3259-40ad-b11f-fff671e95bc1', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', 16,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["nationaalsocialisme", "Volksgemeinschaft", "werkloosheid", "crisis jaren '30", "indoctrinatie", "kenmerkend aspect"]'::jsonb,
   $$Met een kenmerkend aspect en bron 10 onderbouwen dat Hitler de werkverschaffingskampen zou gebruiken om de jeugd te nazificeren.$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-vraag16.png$$, $$Gebruik bron 10. Een bewering: Gareth Jones verwacht dat Hitler gebruik gaat maken van de werkverschaffingskampen om het nationaalsocialisme in praktijk te brengen. 3p 16 Onderbouw deze bewering door:
− het kenmerkend aspect van de twintigste eeuw te noemen waarmee je de oprichting van de werkverschaffingskampen kunt verklaren, en
− aan te geven op welke wijze juist deze kampen kunnen worden ingezet om Duitsland te nazificeren, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['9e363ac7-16d4-4efd-8339-d1677a9f71c6']::uuid[]),
  ('46f193cd-1396-4186-b592-db20ad238626', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', 17,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["communisten", "Rijksdagbrand", "SED", "oprichting DDR", "Koude Oorlog", "Oost-Berlijn"]'::jsonb,
   $$Verklaren waarom communisten in 1933 werden gearresteerd en waarom de SED de verhuizing van Anna Seghers in 1950 toejuichte.$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-vraag17.png$$, $$Anna Seghers was een bekende Duitse schrijfster uit de twintigste eeuw. Haar leven werd beïnvloed door de politieke omstandigheden in Duitsland:
1 In 1933 werd ze als lid van de Duitse communistische partij gearresteerd en korte tijd gevangengehouden.
2 Haar verhuizing in 1950 van West- naar Oost-Berlijn werd toegejuicht door de SED (de communistische partij). 3p 17 Licht dit toe door:
− aan te geven naar aanleiding van welke gebeurtenis communisten in Duitsland werden gearresteerd in 1933, en
− met een gebeurtenis uit 1949 uit te leggen waardoor de SED de verhuizing van Anna Seghers toejuichte.$$, array[]::uuid[]),
  ('c0edd4c8-0e91-4128-a9b1-5c2095950c61', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', 19,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Koude Oorlog", "Radio Free Europe", "detente", "Gorbatsjov", "glasnost", "propaganda"]'::jsonb,
   $$De besluiten van de Sovjet-Unie over Radio Free Europe in 1950 en 1988 uitleggen vanuit het politieke beleid van dat moment.$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-vraag19.png$$, $$Met steun van de Amerikaanse overheid werd in 1950 de radiozender Radio Free Europe (Radio Vrij Europa) opgericht, die vanuit West-Duitsland radioprogramma''s uitzond in onder meer het Pools, Tsjechisch en Roemeens. De Sovjet-Unie besloot:
1 in 1950 de uitzendingen van Radio Free Europe te verstoren, zodat het beluisteren ervan moeilijker werd.
2 in 1988 te stoppen met het verstoren van de uitzendingen van Radio Free Europe. 4p 19 Leg beide besluiten uit vanuit het politieke beleid van de Sovjet-Unie in Oost-Europa op dat moment.$$, array[]::uuid[]),
  ('38501171-d10f-4429-95c2-1455294c65b8', 'd896b9a2-b1d1-44ab-be63-7437c8de02e0', 24,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["DDR", "propaganda", "Sovjet-Unie", "Warschaupact", "ruimtevaart", "bronverwijzing"]'::jsonb,
   $$Met foto en titel uitleggen welke twee boodschappen de communistische partij aan de Oost-Duitse bevolking wilde overbrengen.$$,
   $$geschiedenis-havo-2023-ii-duitsland-in-europa-vraag24.png$$, $$Gebruik bron 12. Met de foto en met de titel van het artikel kan de communistische partij twee boodschappen overbrengen aan de Oost-Duitse bevolking. Een boodschap over:
− de relatie met de Sovjet-Unie, en
− de regering van de DDR. 4p 24 Leg uit welke twee boodschappen worden overgebracht, telkens met een andere verwijzing naar de bron.$$, array['ca76e90d-c813-4566-b196-393ebf6d201d']::uuid[]),
  ('f8f87ba5-400f-42c1-a5a1-3b9152e17754', 'cb2f2ae6-28b2-45c8-9138-c389fee0fc1e', 20,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["consumptiemaatschappij", "Duitse bezetting", "digitale revolutie", "Verdrag van Schengen", "oliecrisis", "chronologie"]'::jsonb,
   $$Bij vier gebeurtenissen in Nederland het gegeven over een winkelketen kiezen dat er een gevolg van is.$$,
   $$geschiedenis-havo-2023-ii-nederland-1948-2008-vraag20.png$$, $$Vijf gegevens over een Nederlandse winkelketen in willekeurige volgorde:
1 Bij de kassa werd een kaart gescand, waarna met de verzamelde gegevens klanten via de mail werden benaderd met aanbiedingen.
2 De toevoer van koffiebonen naar Nederland werd stopgezet, waarna de winkelketen koffiesurrogaat verkocht met de naam Smalsko (''smaakt als koffie'').
3 De vuilniszakken werden duurder vanwege een tekort aan de grondstof olie.
4 In de distributiecentrums werkten duizenden uitzendkrachten, waarvan het merendeel uit Polen kwam.
5 Klanten spaarden zegels, waarna ze die konden inwisselen voor non-food artikelen. Vooral de koelkast was populair. Hieronder staan vier gebeurtenissen in Nederland, in chronologische volgorde: a de Duitse bezetting b het ontstaan van een consumptiemaatschappij c de start van de digitale revolutie d het uitvoeren van het Verdrag van Schengen 2p 20 Geef per gebeurtenis aan welk gegeven daarvan het gevolg is. Noteer alleen de letter en het daarbij passende nummer. Let op: er blijft één gegeven over.$$, array[]::uuid[]),
  ('4f6fd647-0d10-42c2-8bcc-6e5f513930d6', 'cb2f2ae6-28b2-45c8-9138-c389fee0fc1e', 21,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["gastarbeiders", "migratie", "industrialisatie", "beeldvorming", "Turkije", "bronverwijzing"]'::jsonb,
   $$Met bron 11 uitleggen dat sommige gastarbeiders een eenzijdig beeld van de Nederlandse samenleving hadden.$$,
   $$geschiedenis-havo-2023-ii-nederland-1948-2008-vraag21.png$$, $$Gebruik bron 11. Een bewering: Bij hun komst naar Nederland hebben sommige gastarbeiders een eenzijdig beeld van de Nederlandse samenleving. 2p 21 Leg deze bewering uit met een verwijzing naar de bron.$$, array['81e23791-3784-4c6c-be29-1d03ce7d9024']::uuid[]),
  ('c396167b-c5d6-4ee4-8b10-4e6af15f82fd', 'cb2f2ae6-28b2-45c8-9138-c389fee0fc1e', 22,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["aardgasvondst Groningen", "welvaartsgroei", "vrije tijd", "consumptiemaatschappij", "recreatie", "historische verklaring"]'::jsonb,
   $$Historische verklaringen geven voor twee veranderingen in de taak van Staatsbosbeheer in de jaren 1960.$$,
   $$geschiedenis-havo-2023-ii-nederland-1948-2008-vraag22.png$$, $$Staatsbosbeheer beheert bos- en natuurgebieden in Nederland. Twee veranderingen in de taak van Staatsbosbeheer in de jaren 1960:
1 De taak om hout als brandstof te leveren werd steeds minder belangrijk.
2 Staatsbosbeheer moest recreatieve voorzieningen gaan beheren en de groeiende bezoekersstroom in goede banen leidden. 2p 22 Geef voor beide veranderingen een historische verklaring.$$, array[]::uuid[]),
  ('5a10c552-6ad1-42bb-afc9-f2b7875873f5', 'cb2f2ae6-28b2-45c8-9138-c389fee0fc1e', 23,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["hippies", "jongerencultuur", "consumptiemaatschappij", "commercialisering", "protestcultuur", "uitgangspunten"]'::jsonb,
   $$Uitleggen bij welk uitgangspunt van de hippies de Hippy Happy beurs van 1967 niet aansloot.$$,
   $$geschiedenis-havo-2023-ii-nederland-1948-2008-vraag23.png$$, $$In 1967 werd in Ahoy in Rotterdam de Hippy Happy beurs gehouden. Op deze beurs werden op grote schaal producten als gitaren, kleding en sieraden verkocht. Om de hippies te trekken traden er bands op. 2p 23 Leg uit bij welk uitgangspunt van de hippies deze beurs niet aansloot.$$, array[]::uuid[]),
  ('2ed8bacd-092e-47c2-9de0-7d778a13d87d', 'cb2f2ae6-28b2-45c8-9138-c389fee0fc1e', 25,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["Lubbers", "bezuinigingen", "kritiek op verzorgingsstaat", "no-nonsensebeleid", "spotprent", "bronverwijzing"]'::jsonb,
   $$Met de prent van Opland aangeven tegen welk beleid van het kabinet-Lubbers de tekenaar zich keert.$$,
